class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int = 3, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super().__init__()
        # Depthwise convolution (groups=in_channels)
        self.depthwise_cuda = nn.Conv2d(in_channels, in_channels, kernel_size, stride=stride, padding=padding, dilation=dilation, groups=in_channels, bias=bias)
        # Pointwise 1x1 convolution
        self.pointwise_cuda = nn.Conv2d(in_channels, out_channels, kernel_size=1, bias=bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Use custom CUDA implementations for both conv layers
        out = self.depthwise_cuda(x)
        out = self.pointwise_cuda(out)
        return out
